import java.util.*;
import java.io.*;

public class Main {
    static long[] solve(long n, List<String> tree, long k) {
        // tree is the level-order list; missing children are the string "null"
        // Write your solution here
        return new long[]{0, 0, 0};
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> t = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            StringTokenizer st = new StringTokenizer(line);
            while (st.hasMoreTokens()) t.add(st.nextToken());
        }
        long n = Long.parseLong(t.get(0));
        long k = Long.parseLong(t.get(t.size() - 1));
        List<String> tree = new ArrayList<>(t.subList(1, t.size() - 1));
        StringBuilder sb = new StringBuilder();
        for (long x : solve(n, tree, k)) sb.append(x).append("\n");
        System.out.print(sb);
    }
}
